from solution import square_Sum


def test_issue_example_n2():
    """Issue example: square_Sum(2) == 10."""
    assert square_Sum(2) == 10  # 1*1 + 3*3 = 1 + 9 = 10


def test_issue_first_one():
    """Issue: sum of squares of first 1 odd natural numbers is 1."""
    assert square_Sum(1) == 1  # 1*1 = 1


def test_issue_first_three():
    """Issue: sum of squares of first 3 odd natural numbers is 35."""
    assert square_Sum(3) == 35  # 1 + 9 + 25 = 35


def test_issue_empty_zero():
    """Issue: sum of squares of first 0 odd natural numbers is 0."""
    assert square_Sum(0) == 0  # empty sum = 0


def test_issue_first_four():
    """Issue: sum of squares of first 4 odd natural numbers is 84."""
    assert square_Sum(4) == 84  # 1 + 9 + 25 + 49 = 84


def test_issue_first_five():
    """Issue: sum of squares of first 5 odd natural numbers is 165."""
    assert square_Sum(5) == 165  # 1 + 9 + 25 + 49 + 81 = 165


def test_issue_first_six():
    """Issue: sum of squares of first 6 odd natural numbers is 286."""
    assert square_Sum(6) == 286  # 1 + 9 + 25 + 49 + 81 + 121 = 286


def test_issue_first_ten():
    """Issue: sum of squares of first 10 odd natural numbers is 1330."""
    assert square_Sum(10) == 1330  # 1+9+25+49+81+121+169+225+289+361 = 1330


def test_issue_first_hundred():
    """Issue: sum of squares of first 100 odd natural numbers is 1333300."""
    assert square_Sum(100) == 1333300  # 100*199*201/3 = 3999900/3 = 1333300


def test_contract_same_input_same_output():
    """Contract: same n gives same sum on repeated calls."""
    assert square_Sum(4) == square_Sum(4)  # 84 == 84 where 84 = 1+9+25+49


def test_contract_larger_n_larger_sum():
    """Contract: larger n gives larger sum of positive squares."""
    assert square_Sum(5) > square_Sum(4)  # 165 > 84 where 165=1+9+25+49+81 and 84=1+9+25+49
